INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json) VALUES ('8b090dec472117f4598b9ad84318272e', '1759263600.418207', 'D05SD5QLG94', 'message', 'EMPLOYEE_0008_SLACK_ID', 'Julia, I need the live-ops and push calendar for the beta buy we start Mon Oct 6 through Sun Nov 2. Every beat players can see in those weeks: which windows it runs in, if anything is held and until when, the push that goes with it, what still has to land before it runs and who owns that, and your recommendation with the trade-offs. Put it in the calendar sheet in your ZM Live Ops folder, link it on the calendar ticket, and send me the recommendation back here. The working rules for it are in my brief, shared with you. This goes into the pivot call, so I need your call, not a list of what we have.', NULL, '1759263600.418207', 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-30T20:20:00.418207Z', '{}');

INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json) VALUES ('2e75e232f5e6206273411a8305ac5d01', '1758213600.552913', 'C08R8CHB0QL', 'message', 'EMPLOYEE_0016_SLACK_ID', 'Halloween one-off: approved from my side for one of the beta weeks. It can take a recurring slot that week, one themed prop set only, no new mechanics, and I sign the object off if it lands before the cut.', '9025d428af1f551a20e303c3acbc545b', '1758121809.236839', 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-18T16:40:00.552913Z', '{}');

INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json) VALUES ('58d06bd55ea4129eaadb726291967d5a', '1759270200.638114', 'D05GU6L0XFH', 'message', 'EMPLOYEE_0016_SLACK_ID', 'Coming back on the Halloween one-off: pulling my ok. Take it off the beta calendar, we are not spending art time on a theme we may not ship at all. Sorry for the flip, my later word on this one is the one that counts.', 'c54310280ca0915181508d6e9b964926', '1759248350.473459', 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-30T22:10:00.638114Z', '{}');

INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json) VALUES ('fa3eee2c614b0741aeb240275f86abf7', '1759265412.481907', 'C0880U9751A', 'message', 'EMPLOYEE_0012_SLACK_ID', 'Re-tested the weekly leaderboard on the current prod build: it still does not start a new week. I killed the app and reopened it twice, played a few levels, and my week is still last week one. Same on the second device.', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-30T20:50:12.481907Z', '{}');

